import { expect, test, uniqueName, type Persona } from "../../fixtures";
import type { APIRequestContext } from "@playwright/test";

const TEN_MIB = 10 * 1024 * 1024;

type ApiAs = (persona: Persona) => Promise<APIRequestContext>;

test.describe("upload vendor documents: invalid uploads", () => {
  async function draftVendor(apiAs: ApiAs) {
    const member = await apiAs("member");
    const res = await member.post("/api/vendors", {
      data: { name: uniqueName("Doc Vendor"), category: "services", contact_email: "ops@northwind-supply.com" },
    });
    expect(res.status(), await res.text()).toBe(201);
    const vendor = await res.json();
    expect(vendor.status).toBe("draft");
    return { member, vendorId: vendor.id as string };
  }

  test("rejects an empty file with empty_file", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const { member, vendorId } = await draftVendor(apiAs);

    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "empty.txt", mimeType: "text/plain", buffer: Buffer.alloc(0) },
      },
    });

    expect(res.status(), await res.text()).toBe(422);
    const body = await res.json();
    expect(body.error?.code, JSON.stringify(body)).toBe("empty_file");
  });

  test("rejects a file one byte over 10 MiB with file_too_large", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const { member, vendorId } = await draftVendor(apiAs);

    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "big.txt", mimeType: "text/plain", buffer: Buffer.alloc(TEN_MIB + 1, "x") },
      },
    });

    expect(res.status(), await res.text()).toBe(413);
    const body = await res.json();
    expect(body.error?.code, JSON.stringify(body)).toBe("file_too_large");
  });

  test("rejects a .exe file with unsupported_type", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const { member, vendorId } = await draftVendor(apiAs);

    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "tool.exe", mimeType: "application/octet-stream", buffer: Buffer.from("MZ") },
      },
    });

    expect(res.status(), await res.text()).toBe(415);
    const body = await res.json();
    expect(body.error?.code, JSON.stringify(body)).toBe("unsupported_type");
  });

  test("rejects an unknown kind with validation_error", { tag: "@DOC-04" }, async ({ apiAs }) => {
    const { member, vendorId } = await draftVendor(apiAs);

    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: "passport",
        file: { name: "note.txt", mimeType: "text/plain", buffer: Buffer.from("hello") },
      },
    });

    expect(res.status(), await res.text()).toBe(422);
    const body = await res.json();
    expect(body.error?.code, JSON.stringify(body)).toBe("validation_error");
  });
});
